<?php
declare(strict_types=1);
if(!defined('ZODEE_INTERNAL')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}
trait ServerOperationsService {
    public function serverRank(string $server,string $account): int {
        if(query('SELECT 1 FROM server_owners WHERE server_id=? AND account_id=?',[$server,$account])->fetchColumn())return 3;
        $role=query('SELECT role FROM server_admins WHERE server_id=? AND account_id=?',[$server,$account])->fetchColumn();return $role==='admin'?2:($role==='moderator'?1:0);
    }
    private function accessServer(string $server,int $rank=1): array {
        $me=$this->requireAccount();if($this->serverRank($server,$me['id'])<$rank)fail(403,'Your server role does not allow this action.');return $me;
    }
    public function accountAllowed(string $server,string $account): void {
        $maintenance=query('SELECT maintenance_at FROM server_owners WHERE server_id=?',[$server])->fetchColumn();if($maintenance&&(int)$maintenance<=time())fail(503,'Server maintenance is pending. Try another server.');
        $ban=query('SELECT reason,expires_at FROM server_bans WHERE server_id=? AND account_id=? AND expires_at>UTC_TIMESTAMP(6)',[$server,$account])->fetch();
        if($ban)fail(403,'Banned from this server until '.$ban['expires_at'].' UTC: '.$ban['reason']);
    }
    private function healthFor(string $server): array {
        $row=query('SELECT snapshot,seen,seen>UTC_TIMESTAMP(6)-INTERVAL 30 SECOND AS fresh FROM server_health WHERE server_id=?',[$server])->fetch();
        return $row?['seen'=>$row['seen'],'fresh'=>(bool)$row['fresh'],'data'=>json_decode($row['snapshot'],true,32,JSON_THROW_ON_ERROR)]:['seen'=>null,'fresh'=>false,'data'=>['maps'=>[],'roster'=>[]]];
    }
    private function configFor(string $server): array {
        $row=query('SELECT revision,settings FROM server_configs WHERE server_id=?',[$server])->fetch();
        return ['revision'=>$row?(int)$row['revision']:0,'settings'=>$row?json_decode($row['settings'],true):['rotation'=>[],'bots'=>[],'difficulty'=>1,'speed'=>100,'voting'=>false]];
    }
    private function checkedSettings(string $server,array $settings): array {
        fields($settings,['rotation','bots','difficulty','speed','voting']);$maps=$settings['rotation']??[];$bots=$settings['bots']??[];
        if(!is_array($maps)||!array_is_list($maps)||count($maps)>16||!is_array($bots)||!array_is_list($bots)||count($bots)>4)fail(400,'Choose at most sixteen rotation maps and four bot teams.');
        $catalog=array_column($this->healthFor($server)['data']['maps'],'map');foreach($maps as $map)if(!is_string($map)||!in_array($map,$catalog,true))fail(400,'A rotation map is not installed on this host. Wait for a fresh catalog.');
        foreach($bots as $bot)int_value($bot,1,4);$difficulty=int_value($settings['difficulty']??1,0,3);$speed=int_value($settings['speed']??100,25,300);$voting=$settings['voting']??false;if(!is_bool($voting))fail(400,'Invalid voting setting.');
        return ['rotation'=>array_values(array_unique($maps)),'bots'=>array_values(array_unique($bots)),'difficulty'=>$difficulty,'speed'=>$speed,'voting'=>$voting];
    }
    public function postServerHealth(array $in): array {
        $server=$this->server();fields($in,['snapshot']);$v=$in['snapshot']??null;if(!is_array($v))fail(400,'Invalid health snapshot.');
        $maps=$v['maps']??[];$roster=$v['roster']??[];if(!is_array($maps)||!is_array($roster)||count($maps)>64||count($roster)>64)fail(400,'Health snapshot exceeds limits.');
        foreach($maps as &$map){if(!is_array($map))fail(400,'Invalid map.');$map['map']=clean_text($map['map']??null,240);if(isset($map['sha256'])&&!is_hex_id($map['sha256']))fail(400,'Invalid map digest.');$map['title']=clean_text($map['title']??$map['map'],120);$map['width']=int_value($map['width']??1,1,4096);$map['height']=int_value($map['height']??1,1,4096);$map['forts']=$map['forts']??[];$map['zones']=$map['zones']??[];if(!is_array($map['forts'])||count($map['forts'])>8||!is_array($map['zones'])||count($map['zones'])>16)fail(400,'Invalid preview geometry.');foreach(array_merge($map['forts'],$map['zones']) as $shape){if(!is_array($shape)||count($shape)>5)fail(400,'Invalid geometry.');foreach($shape as $n)int_value($n,0,65536);}}unset($map);
        foreach($roster as &$person){if(!is_array($person)||!is_hex_id($person['account']??null))fail(400,'Invalid authenticated player.');$person=['account'=>$person['account'],'name'=>clean_text($person['name']??null,24)];}unset($person);
        $out=['maps'=>$maps,'roster'=>$roster,'round'=>clean_text($v['round']??'unknown',40),'intermission'=>(bool)($v['intermission']??false),'next_map'=>clean_text($v['next_map']??'',240,true)];
        foreach(['tick_ms','uptime','role_age','outbox','applied_revision','sync_checks','sync_mismatches'] as $key){$value=$v[$key]??0;if(!is_numeric($value)||!is_finite((float)$value)||(float)$value<0||(float)$value>1e12)fail(400,'Invalid health metric.');$out[$key]=0+$value;}$out['cloud_ok']=($v['cloud_ok']??false)===true;
        $out['build_id']=clean_text($v['build_id']??'Unknown',160);$out['engine_version']=clean_text($v['engine_version']??'0.7.0',80);
        $runtime=$v['runtime']??[];if(!is_array($runtime))fail(400,'Invalid runtime status.');$out['runtime']=[];foreach(['running','staged','previous','outcome','outcome_at'] as $key)$out['runtime'][$key]=clean_text((string)($runtime[$key]??'Unknown'),240);
        $out['vote_closes']=time()+min(25,max(0,(float)($v['vote_remaining']??0)));
        $json=json_encode($out,JSON_THROW_ON_ERROR);if(strlen($json)>60000)fail(413,'Health snapshot too large.');
        query('DELETE FROM server_map_votes WHERE server_id=? AND round_id<>?',[$server,$out['round']]);
        query('INSERT INTO server_health(server_id,snapshot) VALUES(?,?) ON DUPLICATE KEY UPDATE snapshot=VALUES(snapshot),seen=UTC_TIMESTAMP(6)',[$server,$json]);return ['ok'=>true];
    }
    public function serverConsole(string $server): array {
        $me=$this->accessServer($server);return ['server'=>$server,'role'=>$this->serverRank($server,$me['id']),'health'=>$this->healthFor($server),'config'=>$this->configFor($server),
            'owner'=>query('SELECT o.hosting_enabled,o.host_revoked,o.maintenance_at,o.maintenance_action,o.maintenance_reason,a.username FROM server_owners o JOIN accounts a ON a.id=o.account_id WHERE o.server_id=?',[$server])->fetch(),
            'admins'=>query('SELECT a.username,s.role FROM server_admins s JOIN accounts a ON a.id=s.account_id WHERE s.server_id=? ORDER BY s.role,a.username',[$server])->fetchAll(),
            'bans'=>query('SELECT a.username,b.reason,b.expires_at FROM server_bans b JOIN accounts a ON a.id=b.account_id WHERE b.server_id=? AND b.expires_at>UTC_TIMESTAMP(6) ORDER BY b.expires_at',[$server])->fetchAll(),
            'presets'=>query('SELECT name FROM server_presets WHERE server_id=? ORDER BY name',[$server])->fetchAll(),
            'audit'=>query('SELECT l.action,l.details,l.created_at,a.username FROM moderation_log l JOIN accounts a ON a.id=l.actor WHERE l.target=? ORDER BY l.id DESC LIMIT 60',[$server])->fetchAll(),
            'commands'=>query('SELECT id,CASE WHEN status=\'pending\' AND expires_at<=UTC_TIMESTAMP(6) THEN \'expired\' ELSE status END AS status,reason,created_at FROM server_commands WHERE server_id=? ORDER BY id DESC LIMIT 20',[$server])->fetchAll()];
    }
    public function operateServer(array $in,?array $hostActor=null): array {
        $this->limit();fields($in,['server','action','username','reason','minutes','settings','name','delay','maintenance_action']);$server=clean_text($in['server']??null,64);$action=$in['action']??'';
        $required=in_array($action,['disable','enable','revoke-host'],true)?3:(in_array($action,['configure','save-preset','load-preset','delete-preset','schedule-maintenance','cancel-maintenance'],true)?2:1);$me=$hostActor??$this->accessServer($server,$required);if($this->serverRank($server,$me['id'])<$required)fail(403,'Insufficient server role.');
        return transaction(function()use($in,$server,$action,$me,$required){
            // Same lock order as enrollment: account, then host key, then owner row.
            $accounts=[$me['id']];if(in_array($action,['kick','ban','unban'],true)){$target=query('SELECT id FROM accounts WHERE username_key=?',[strtolower(clean_text($in['username']??null,24))])->fetchColumn();if(!$target)fail(404,'Account not found.');$accounts[]=$target;}sort($accounts);foreach(array_unique($accounts) as $account)query('SELECT id FROM accounts WHERE id=? FOR UPDATE',[$account]);query('SELECT id FROM server_keys WHERE id=? FOR UPDATE',[$server]);query('SELECT server_id FROM server_owners WHERE server_id=? FOR UPDATE',[$server]);
            if($this->serverRank($server,$me['id'])<$required)fail(403,'Server role changed.');$details='';$commandID=null;
            if(in_array($action,['disable','enable','revoke-host'],true)){
                if($action==='revoke-host')query('UPDATE server_keys SET key_hash=? WHERE id=?',[token_hash(random_token()),$server]);
                query('UPDATE server_owners SET '.($action==='revoke-host'?'host_revoked=1':'hosting_enabled=?').' WHERE server_id=?',$action==='revoke-host'?[$server]:[$action==='enable'?1:0,$server]);
                if($action!=='enable'){query('DELETE FROM servers WHERE id=?',[$server]);query('DELETE FROM join_tickets WHERE server_id=?',[$server]);query('DELETE FROM native_connections WHERE server_id=?',[$server]);query('DELETE FROM server_auth_requests WHERE server_id=?',[$server]);}
            }elseif(in_array($action,['schedule-maintenance','cancel-maintenance'],true)){
                $at=0;$reason='';$mode='stop';if($action==='schedule-maintenance'){$at=time()+int_value($in['delay']??300,30,86400);$reason=clean_text($in['reason']??null,160);$mode=$in['maintenance_action']??'stop';if(!in_array($mode,['stop','restart'],true))fail(400,'Invalid maintenance action.');}
                query('UPDATE server_owners SET maintenance_at=?,maintenance_reason=?,maintenance_action=? WHERE server_id=?',[$at,$reason,$mode,$server]);$details=$action==='cancel-maintenance'?'Cancelled':$mode.' at '.gmdate('c',$at).': '.$reason;
            }elseif(in_array($action,['kick','ban','unban'],true)){
                $name=clean_text($in['username']??null,24);$target=query('SELECT id FROM accounts WHERE username_key=?',[strtolower($name)])->fetchColumn();if(!$target)fail(404,'Account not found.');
                if($this->serverRank($server,$target)>=$this->serverRank($server,$me['id']))fail(403,'You cannot moderate the owner or an equal/higher server role.');
                if($action==='unban')query('DELETE FROM server_bans WHERE server_id=? AND account_id=?',[$server,$target]);
                else {$reason=clean_text($in['reason']??null,160);if($action==='ban'){$minutes=int_value($in['minutes']??60,1,10080);query('INSERT INTO server_bans(server_id,account_id,reason,expires_at) VALUES(?,?,?,UTC_TIMESTAMP(6)+INTERVAL ? MINUTE) ON DUPLICATE KEY UPDATE reason=VALUES(reason),expires_at=VALUES(expires_at)',[$server,$target,$reason,$minutes]);}query('INSERT INTO server_commands(server_id,actor,target,reason,expires_at) VALUES(?,?,?,?,UTC_TIMESTAMP(6)+INTERVAL 60 SECOND)',[$server,$me['id'],$target,$reason]);$commandID=(string)db()->lastInsertId();}
                $details=$name.($action==='unban'?'':': '.$reason);
            }elseif(in_array($action,['configure','save-preset','load-preset','delete-preset'],true)){
                if($action==='load-preset'){$name=clean_text($in['name']??null,40);$json=query('SELECT settings FROM server_presets WHERE server_id=? AND name=?',[$server,$name])->fetchColumn();if(!$json)fail(404,'Preset not found.');$settings=$this->checkedSettings($server,json_decode($json,true));}
                elseif($action!=='delete-preset'){$raw=$in['settings']??[];if(!is_array($raw))fail(400,'Invalid settings.');$settings=$this->checkedSettings($server,$raw);}
                if(in_array($action,['configure','load-preset'],true))query('INSERT INTO server_configs(server_id,settings) VALUES(?,?) ON DUPLICATE KEY UPDATE revision=revision+1,settings=VALUES(settings)',[$server,json_encode($settings,JSON_THROW_ON_ERROR)]);
                else {$name=clean_text($in['name']??null,40);if($action==='delete-preset')query('DELETE FROM server_presets WHERE server_id=? AND name=?',[$server,$name]);else {if(query('SELECT COUNT(*) FROM server_presets WHERE server_id=?',[$server])->fetchColumn()>=32&&!query('SELECT 1 FROM server_presets WHERE server_id=? AND name=?',[$server,$name])->fetchColumn())fail(429,'Preset limit reached.');query('INSERT INTO server_presets(server_id,name,settings) VALUES(?,?,?) ON DUPLICATE KEY UPDATE settings=VALUES(settings)',[$server,$name,json_encode($settings,JSON_THROW_ON_ERROR)]);}$details=$name;}
            }else fail(400,'Unknown server action.');
            query('INSERT INTO moderation_log(actor,action,target,details) VALUES(?,?,?,?)',[$me['id'],'server-'.$action,$server,$details]);return ['ok'=>true,'command'=>$commandID];
        });
    }
    public function serverControl(): array {
        $server=$this->server();$roles=$this->serverRoles();$config=$this->configFor($server);$health=$this->healthFor($server);$round=$health['data']['round']??'';
        $counts=query('SELECT map_id,COUNT(*) AS votes FROM server_map_votes WHERE server_id=? AND round_id=? GROUP BY map_id ORDER BY votes DESC,map_id',[$server,$round])->fetchAll();$winner='';foreach($counts as $count)foreach($config['settings']['rotation'] as $map)if(hash('sha256',$map)===$count['map_id']&&$winner==='')$winner=$map;
        $bans=query('SELECT account_id AS account,reason,UNIX_TIMESTAMP(expires_at) AS expires FROM server_bans WHERE server_id=? AND expires_at>UTC_TIMESTAMP(6) LIMIT 128',[$server])->fetchAll();foreach($bans as &$ban)$ban['expires']=(int)$ban['expires'];unset($ban);
        return $roles+['maintenance'=>query('SELECT maintenance_at AS at,maintenance_action AS action,maintenance_reason AS reason FROM server_owners WHERE server_id=?',[$server])->fetch(),'bans'=>$bans,
            'commands'=>query('SELECT id,actor,target,reason FROM server_commands WHERE server_id=? AND status=\'pending\' AND expires_at>UTC_TIMESTAMP(6) ORDER BY id LIMIT 32',[$server])->fetchAll(),'config'=>$config,'winner'=>$winner,'winner_round'=>$round];
    }
    public function completeMaintenance(array $in): array {$server=$this->server();fields($in,['at']);$at=int_value($in['at']??null,1,PHP_INT_MAX);query('UPDATE server_owners SET maintenance_at=0 WHERE server_id=? AND maintenance_at=?',[$server,$at]);return ['ok'=>true];}
    public function hostModerate(array $in): array {
        $server=$this->server();fields($in,['actor','target','action','reason','minutes']);if(!is_hex_id($in['actor']??null)||!is_hex_id($in['target']??null)||!in_array($in['action']??'', ['kick','ban'],true))fail(400,'Invalid moderation request.');
        $name=query('SELECT username FROM accounts WHERE id=?',[$in['target']])->fetchColumn();if(!$name)fail(404,'Account not found.');
        return $this->operateServer(['server'=>$server,'username'=>$name,'action'=>$in['action'],'reason'=>$in['reason']??'','minutes'=>$in['minutes']??60],['id'=>$in['actor']]);
    }
    public function nativeModerationStatus(array $in): array {
        $server=$this->server();fields($in,['actor','command']);if(!is_hex_id($in['actor']??null)||!is_string($in['command']??null)||!ctype_digit($in['command'])||strlen($in['command'])>18)fail(400,'Invalid status request.');if($this->serverRank($server,$in['actor'])<1)fail(403,'Server role revoked.');
        $row=query('SELECT CASE WHEN status=\'pending\' AND expires_at<=UTC_TIMESTAMP(6) THEN \'expired\' ELSE status END AS status FROM server_commands WHERE server_id=? AND actor=? AND id=?',[$server,$in['actor'],$in['command']])->fetch();if(!$row)fail(404,'Moderation action not found.');return $row;
    }
    public function exportPreset(string $server,string $name): array {
        $this->accessServer($server,2);$json=query('SELECT settings FROM server_presets WHERE server_id=? AND name=?',[$server,clean_text($name,40)])->fetchColumn();if(!$json)fail(404,'Preset not found.');$settings=json_decode($json,true);$catalog=array_column($this->healthFor($server)['data']['maps'],null,'map');$rotation=[];
        foreach($settings['rotation'] as $path){$map=$catalog[$path]??null;if(!$map||!is_hex_id($map['sha256']??null))fail(409,'Wait for a fresh host map catalog before exporting.');$rotation[]=['file'=>basename($path),'sha256'=>$map['sha256']];}$settings['rotation']=$rotation;
        return ['format'=>'zod-enhanced-server-preset','schema'=>1,'engine_min'=>'0.7.0','name'=>$name,'settings'=>$settings];
    }
    public function importPreset(array $in,bool $save=false): array {
        fields($in,['server','document']);$server=clean_text($in['server']??null,64);$this->accessServer($server,2);$doc=$in['document']??null;if(!is_array($doc))fail(400,'Invalid preset document.');fields($doc,['format','schema','engine_min','name','settings']);if(($doc['format']??'')!=='zod-enhanced-server-preset'||($doc['schema']??0)!==1||!is_string($doc['engine_min']??null)||!preg_match('/\A[0-9]+\.[0-9]+\.[0-9]+\z/',$doc['engine_min']))fail(400,'Unsupported preset format.');$name=clean_text($doc['name']??null,40);$health=$this->healthFor($server);if(!$health['fresh'])fail(409,'Wait for a fresh host map catalog.');$version=$health['data']['engine_version']??'0.7.0';if(version_compare($version,$doc['engine_min'],'<'))fail(409,'This preset needs a newer engine.');$settings=$doc['settings']??null;if(!is_array($settings)||!is_array($settings['rotation']??null)||!array_is_list($settings['rotation'])||count($settings['rotation'])>16)fail(400,'Invalid rotation.');$resolved=[];$unresolved=[];
        foreach($settings['rotation'] as $ref){if(!is_array($ref)||!is_hex_id($ref['sha256']??null)||!is_string($ref['file']??null)||strlen($ref['file'])>120||basename($ref['file'])!==$ref['file']||str_contains($ref['file'],'\\'))fail(400,'Invalid portable map reference.');$matches=array_values(array_filter($health['data']['maps'],fn($m)=>($m['sha256']??'')===$ref['sha256']));if(!$matches)$unresolved[]=$ref['file'];else{$chosen=$matches[0];foreach($matches as $m)if(basename($m['map'])===$ref['file'])$chosen=$m;$resolved[]=$chosen['map'];}}
        $settings['rotation']=$resolved;$settings=$this->checkedSettings($server,$settings);if($save){if($unresolved)fail(409,'Install missing rotation maps before importing.');$this->operateServer(['server'=>$server,'action'=>'save-preset','name'=>$name,'settings'=>$settings]);}
        return ['name'=>$name,'replaces_existing'=>(bool)query('SELECT 1 FROM server_presets WHERE server_id=? AND name=?',[$server,$name])->fetchColumn(),'settings'=>$settings,'missing_maps'=>$unresolved,'compatible'=>!$unresolved,'saved'=>$save];
    }
    public function acknowledgeServerCommands(array $in): array {
        $server=$this->server();fields($in,['results']);$results=$in['results']??null;if(!is_array($results)||count($results)>32)fail(400,'Invalid command acknowledgements.');
        foreach($results as $r){if(!is_array($r)||!is_string($r['id']??null)||!ctype_digit($r['id'])||strlen($r['id'])>18||!is_bool($r['applied']??null))fail(400,'Invalid acknowledgement.');query('UPDATE server_commands SET status=? WHERE id=? AND server_id=? AND status=\'pending\' ',[$r['applied']?'applied':'rejected',$r['id'],$server]);}return ['ok'=>true];
    }
    public function rotationView(string $server): array {
        if(!in_array($server,array_column($this->servers(),'id'),true))fail(404,'Server is offline.');$health=$this->healthFor($server);$config=$this->configFor($server);$maps=[];
        foreach($health['data']['maps'] as $map)if(in_array($map['map'],$config['settings']['rotation'],true)){$map['id']=hash('sha256',$map['map']);unset($map['map']);$maps[]=$map;}
        return ['server'=>$server,'maps'=>$maps,'next'=>$health['data']['next_map']??'','round'=>$health['data']['round']??'','voting'=>$config['settings']['voting']&&$health['fresh']&&($health['data']['intermission']??false)&&($health['data']['vote_closes']??0)>time()];
    }
    public function voteServerMap(array $in): array {
        $this->limit();$me=$this->requireAccount();fields($in,['server','round','map']);$server=clean_text($in['server']??null,64);$this->accountAllowed($server,$me['id']);$view=$this->rotationView($server);
        if(!$view['voting']||($in['round']??'')!==$view['round']||!in_array($in['map']??'',array_column($view['maps'],'id'),true))fail(409,'Voting is closed or this round changed. Refresh the page.');
        if(!in_array($me['id'],array_column($this->healthFor($server)['data']['roster'],'account'),true))fail(403,'Only connected participants may vote.');
        query('INSERT INTO server_map_votes(server_id,round_id,account_id,map_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE map_id=VALUES(map_id)',[$server,$view['round'],$me['id'],$in['map']]);return ['ok'=>true];
    }
}
function server_ops_form(string $csrf,string $server,string $action,string $label,array $fields=[]):void { ?>
<form action="/server-console" method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($server)?>"><input type="hidden" name="action" value="<?=e($action)?>"><?php foreach($fields as $key=>$value):?><input type="hidden" name="<?=e($key)?>" value="<?=e($value)?>"><?php endforeach?><button class="button"><?=e($label)?></button></form><?php }
function server_map_svg(array $map):void {
    $w=max(1,(int)$map['width']);$h=max(1,(int)$map['height']);?><svg class="map-tactical" viewBox="0 0 <?=$w?> <?=$h?>" role="img" aria-label="Tactical layout: <?=e($map['title'])?>"><rect width="100%" height="100%" fill="#243541"/><?php foreach($map['zones'] as $z):if(count($z)<4)continue;?><rect x="<?=(int)$z[0]?>" y="<?=(int)$z[1]?>" width="<?=(int)$z[2]?>" height="<?=(int)$z[3]?>" fill="none" stroke="#8c9aa5" stroke-width="<?=max(0.5,$w/180)?>"/><?php endforeach;foreach($map['forts'] as $f):if(count($f)<3)continue;$colors=['#aaa','#ef6860','#559bff','#7ac57a','#e8c75e'];?><circle cx="<?=(int)$f[0]?>" cy="<?=(int)$f[1]?>" r="<?=max(1,$w/35)?>" fill="<?=$colors[min(4,max(0,(int)$f[2]))]?>"/><?php endforeach?></svg><?php
}
function server_console_page(ZodService $service,string $csrf):void {
    $id=is_string($_GET['server']??null)?$_GET['server']:'';$v=$service->serverConsole($id);$h=$v['health'];$d=$h['data'];$settings=$v['config']['settings'];?><section class="shell section page-section"><?php title_block('MY SERVERS / OPERATIONS',$id,'Moderators handle players. Administrators configure matches. Owners manage hosting credentials and role membership.');?><p><a href="/my-servers">My servers &amp; roles</a> · <a href="/server-rotation?server=<?=e($id)?>">Next map &amp; player voting</a></p><nav aria-label="Server dashboard sections" class="button-row"><a class="button" href="#server-health">Health &amp; updates</a><a class="button" href="#server-access">Ownership &amp; roles</a><a class="button" href="#server-players">Players &amp; bans</a><a class="button" href="#server-presets">Rotation &amp; presets</a><a class="button" href="#server-history">Audit history</a></nav><article id="server-health" class="panel panel-pad"><h2>Server health</h2><p>Build: <code><?=e($d['build_id']??'Unknown')?></code></p><h3>Engine update status</h3><dl><?php foreach(['running'=>'Running','staged'=>'Staged','previous'=>'Rollback version','outcome'=>'Last update result','outcome_at'=>'Result time (UTC)'] as $key=>$label):?><dt><?=e($label)?></dt><dd><?=e($d['runtime'][$key]??'Unknown')?></dd><?php endforeach?></dl><p><a href="/match-history?server=<?=e(rawurlencode($id))?>">Completed matches on this server</a></p><p role="status"><?=$h['fresh']?'Recent host report':'Offline or stale report — values below may be outdated'?> · <?=e($h['seen']??'Not reported')?> UTC</p><dl class="server-health"><?php foreach(['tick_ms'=>'Simulation work per tick (ms)','uptime'=>'Uptime (seconds)','role_age'=>'Age of cloud roles (seconds)','outbox'=>'Pending statistics uploads','applied_revision'=>'Applied configuration','sync_checks'=>'State checks received','sync_mismatches'=>'State mismatches reported'] as $key=>$label):?><div><dt><?=e($label)?></dt><dd><?=e($d[$key]??'Unknown')?></dd></div><?php endforeach?></dl><p>Cloud refresh: <?=($d['cloud_ok']??false)?'Available at last report':'Unavailable / not confirmed'?>. Desired configuration: <?=e($v['config']['revision'])?>.</p></article>
<article id="server-access" class="panel panel-pad"><h2>Ownership and delegated roles</h2><p>Owner: <strong><?=e($v['owner']['username']??'Unknown')?></strong>. Your role: <?=e([1=>'Moderator',2=>'Administrator',3=>'Owner'][$v['role']])?>.</p><?php if(!$v['admins']):?><p>No delegated accounts.</p><?php endif;foreach($v['admins'] as $admin):?><div class="button-row"><span><?=e($admin['username'])?> · <?=e($admin['role'])?></span><?php if($v['role']===3):?><form action="/my-servers/admin" method="post"><input type="hidden" name="return_console" value="1"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><input type="hidden" name="username" value="<?=e($admin['username'])?>"><input type="hidden" name="action" value="remove"><button class="button">Remove role for <?=e($admin['username'])?></button></form><?php endif?></div><?php endforeach;if($v['role']===3):?><form action="/my-servers/admin" method="post" class="account-form"><input type="hidden" name="return_console" value="1"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><input type="hidden" name="action" value="add"><label>Cloud username<input name="username" maxlength="24" required></label><label>Role<select name="role"><option value="admin">Administrator</option><option value="moderator">Moderator</option></select></label><button class="button">Assign role</button></form><?php endif?><p>Role changes take about ten seconds to reach a connected host. Owners retain permanent administration.</p></article><article class="panel panel-pad"><h2>Maintenance</h2><p><?=((int)$v['owner']['maintenance_at'])?'Scheduled '.e(gmdate('Y-m-d H:i:s',(int)$v['owner']['maintenance_at'])).' UTC: '.e($v['owner']['maintenance_reason']):'No maintenance scheduled'?>. Active rounds finish before shutdown; new joins stop at the scheduled time.</p><?php if($v['role']>=2):?><form action="/server-console" method="post" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><label>Delay (seconds)<input type="number" name="delay" min="30" max="86400" value="300" required></label><label>Reason<input name="reason" maxlength="160" required></label><label>After the round<select name="maintenance_action"><option value="stop">Stop</option><option value="restart">Restart / apply staged update</option></select></label><button class="button" name="action" value="schedule-maintenance">Schedule maintenance</button></form><?php server_ops_form($csrf,$id,'cancel-maintenance','Cancel maintenance');endif?></article>
<?php if($v['role']===3):?><article class="panel panel-pad"><h2>Owner security</h2><p>Owner hosting: <?=$v['owner']['hosting_enabled']?'enabled':'disabled'?>. Host credential: <?=$v['owner']['host_revoked']?'revoked — authorize the host again':'active'?>. Site-operator disables cannot be overridden here.</p><div class="button-row"><?php server_ops_form($csrf,$id,$v['owner']['hosting_enabled']?'disable':'enable',$v['owner']['hosting_enabled']?'Disable my server':'Enable my server');server_ops_form($csrf,$id,'revoke-host','Revoke host credential');?></div><p class="small">Disabling or revoking removes the listing and pending joins. Current players may finish; cloud administration stops. A revoked host must sign in again.</p></article><?php endif?>
<article id="server-players" class="panel panel-pad"><h2>Connected accounts</h2><?php foreach($d['roster']??[] as $person):?><p><?=e($person['name'])?></p><?php endforeach?><form class="account-form" action="/server-console" method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><label>Cloud username<input name="username" maxlength="24" required list="server-players"></label><datalist id="server-players"><?php foreach($d['roster']??[] as $person):?><option value="<?=e($person['name'])?>"><?php endforeach?></datalist><label>Reason<input name="reason" maxlength="160" required></label><label>Ban duration<select name="minutes"><option value="15">15 minutes</option><option value="60">1 hour</option><option value="1440">1 day</option><option value="10080">7 days</option></select></label><div class="button-row"><button class="button" name="action" value="kick">Kick once</button><button class="button" name="action" value="ban">Temporarily ban</button></div></form><p class="small">You cannot moderate an equal/higher role or the owner. Kicks expire after a minute if the host is offline.</p><h3>Active bans</h3><?php foreach($v['bans'] as $ban):?><p><?=e($ban['username'])?> — <?=e($ban['reason'])?> — until <?=e($ban['expires_at'])?> UTC</p><?php server_ops_form($csrf,$id,'unban','Remove ban',['username'=>$ban['username']]);endforeach?></article>
<?php if($v['role']>=2):?><article id="server-presets" class="panel panel-pad"><h2>Rotation and match presets</h2><p>Changes apply in the next lobby, not in the middle of a round. Rotation follows the displayed map order. Select a map and use Move up/down to reorder it. Tactical previews show forts and territory boundaries.</p><form action="/server-console" method="post" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><input type="hidden" name="configure_form" value="1"><label>Rotation maps (use Ctrl/Cmd to select several)<select name="rotation[]" data-rotation-order multiple size="8"><?php foreach(array_values(array_filter(array_map(fn($path)=>array_column($d['maps']??[],null,'map')[$path]??null,array_unique(array_merge($settings['rotation'],array_column($d['maps']??[],'map')))))) as $map):?><option value="<?=e($map['map'])?>" <?=in_array($map['map'],$settings['rotation'],true)?'selected':''?>><?=e($map['title'])?> (<?=e($map['width'])?> × <?=e($map['height'])?>)</option><?php endforeach?></select></label><label>Difficulty<select name="difficulty"><?php foreach(['Easy','Normal','Hard','Expert'] as $n=>$label):?><option value="<?=$n?>" <?=$settings['difficulty']===$n?'selected':''?>><?=$label?></option><?php endforeach?></select></label><label>Game speed (%)<input name="speed" type="number" min="25" max="300" value="<?=e($settings['speed'])?>" required></label><fieldset><legend>Bot teams for the next lobby</legend><?php foreach(['Red','Blue','Green','Yellow'] as $i=>$label):?><label><input type="checkbox" name="bots[]" value="<?=$i+1?>" <?=in_array($i+1,$settings['bots'],true)?'checked':''?>> <?=$label?></label><?php endforeach?></fieldset><label><input name="voting" type="checkbox" value="1" <?=$settings['voting']?'checked':''?>> Allow connected players to vote between rounds</label><label>Preset name (for Save preset)<input name="name" maxlength="40"></label><div class="button-row"><button class="button" name="action" value="configure">Apply to next lobby</button><button class="button" name="action" value="save-preset">Save named preset</button></div></form><p><a href="/server-presets?server=<?=e(rawurlencode($id))?>">Download or preview/import presets</a></p><h3>Saved presets</h3><?php foreach($v['presets'] as $preset):?><p><?=e($preset['name'])?></p><div class="button-row"><?php server_ops_form($csrf,$id,'load-preset','Apply preset',['name'=>$preset['name']]);server_ops_form($csrf,$id,'delete-preset','Delete preset',['name'=>$preset['name']]);?></div><?php endforeach?></article><?php endif?>
<article id="server-history" class="panel panel-pad"><h2>Server audit history</h2><div class="table-scroll"><table><thead><tr><th>UTC</th><th>Account</th><th>Action</th><th>Details</th></tr></thead><tbody><?php foreach($v['audit'] as $event):?><tr><td><?=e($event['created_at'])?></td><td><?=e($event['username'])?></td><td><?=e($event['action'])?></td><td><?=e($event['details'])?></td></tr><?php endforeach?></tbody></table></div><h3>Recent kick delivery</h3><?php foreach($v['commands'] as $command):?><p>#<?=e($command['id'])?> · <?=e($command['status'])?> · <?=e($command['reason'])?></p><?php endforeach?></article></section><?php
}
function server_rotation_page(ZodService $service,string $csrf):void {
    $id=is_string($_GET['server']??null)?$_GET['server']:'';$v=$service->rotationView($id);?><section class="shell section page-section"><?php title_block('PUBLIC SERVER / NEXT MAP',$id,'Preview the rotation and vote during the between-round window. One vote per connected account; submitting again changes your vote.');?><p>Next map: <?=e(basename($v['next']))?>. <?=$v['voting']?'Voting is open now.':'Voting is closed. Refresh after the round ends.'?></p><div class="enhancement-grid"><?php foreach($v['maps'] as $map):?><article class="panel panel-pad"><h2><?=e($map['title'])?></h2><?php server_map_svg($map);?><p><?=e($map['width'])?> × <?=e($map['height'])?></p><?php if($v['voting']):?><form action="/server-rotation/vote" method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><input type="hidden" name="round" value="<?=e($v['round'])?>"><input type="hidden" name="map" value="<?=e($map['id'])?>"><button class="button">Vote for this map</button></form><?php endif?></article><?php endforeach?></div><?php if(!$v['maps']):?><p>No rotation configured; this server repeats its current map.</p><?php endif?></section><?php
}
function match_history_page(ZodService $service):void {
 $id=is_string($_GET['id']??null)?$_GET['id']:'';$server=is_string($_GET['server']??null)?$_GET['server']:'';
 ?><section class="shell section page-section"><?php title_block('NETWORK / MATCH RECORDS','Battle history','Completed public matches. Private profiles are anonymized; private games are never uploaded.');
 if($id!==''){$m=$service->matchDetails($id);?><article class="panel panel-pad"><h2><?=e(basename($m['map_name']))?></h2><p><?=e($m['server_id'])?> · <?=e($m['finished_at'])?> UTC · <?=e($m['duration'])?> seconds</p><div class="table-scroll"><table><caption>Participants and results</caption><thead><tr><th>Commander</th><th>Team</th><th>Result</th><th>Kills</th><th>Lost</th><th>Captures</th></tr></thead><tbody><?php foreach($m['players'] as $p):?><tr><td><?=e($p['username'])?></td><td><?=e(['Unknown','R / Red','B / Blue','G / Green','Y / Yellow'][$p['team']]??'Unknown')?></td><td><?=$p['won']?'Victory':'Defeat'?></td><td><?=e($p['kills'])?></td><td><?=e($p['lost'])?></td><td><?=e($p['captures'])?></td></tr><?php endforeach?></tbody></table></div></article><p><a href="/match-history?server=<?=e(rawurlencode($m['server_id']))?>">More matches on this server</a></p><?php
 }else{$before=is_string($_GET['before']??null)?$_GET['before']:'';$rows=$service->matchHistory($server,$before);?><div class="panel panel-pad"><h2><?=e($server?:'All public servers')?></h2><?php foreach($rows as $m):?><p><a href="/match-history?id=<?=e($m['id'])?>"><?=e(basename($m['map_name']))?></a> · <?=e($m['server_id'])?> · <?=e($m['duration'])?>s · <?=e($m['finished_at'])?> UTC</p><?php endforeach;if(!$rows):?><p>No completed matches recorded yet.</p><?php endif;if(count($rows)===25):?><a class="button" href="/match-history?server=<?=e(rawurlencode($server))?>&amp;before=<?=e(end($rows)['id'])?>">Older matches</a><?php endif?></div><?php }?></section><?php
}
function server_presets_page(ZodService $service,string $csrf):void {
 $id=is_string($_GET['server']??null)?$_GET['server']:(is_string($_POST['server']??null)?$_POST['server']:'');$v=$service->serverConsole($id);if($v['role']<2)fail(403,'Preset sharing requires administrator access.');$preview=$_POST['preview_result']??null;$document=is_string($_POST['document']??null)?$_POST['document']:'';
 ?><section class="shell section page-section"><?php title_block('SERVER / PORTABLE PRESETS','Share match settings','Presets contain settings and map checksums. They contain no accounts, credentials or host paths. Importing saves a named preset; it does not change an active match.');?><div class="panel panel-pad"><h2>Download</h2><?php foreach($v['presets'] as $p):?><p><a href="/server-presets/download?server=<?=e(rawurlencode($id))?>&amp;name=<?=e(rawurlencode($p['name']))?>"><?=e($p['name'])?> — JSON preset</a></p><?php endforeach?></div><div class="panel panel-pad"><h2>Preview an import</h2><form method="post" action="/server-presets" enctype="multipart/form-data" class="account-form"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="server" value="<?=e($id)?>"><label>Upload preset JSON<input type="file" name="preset_file" accept="application/json,.json"></label><label>Or paste preset JSON (maximum 32 KiB)<textarea name="document" rows="12" maxlength="32768"><?=e($document)?></textarea></label><button class="button" name="action" value="preview">Check compatibility</button><?php if($preview):?><h3><?=e($preview['name'])?></h3><?php if($preview['replaces_existing']&&!$preview['saved']):?><p>This will replace the existing named preset. The active match is unchanged.</p><?php endif?><p><?=$preview['saved']?'Preset saved.':($preview['compatible']?'Compatible with this host.':'Missing maps: '.e(implode(', ',$preview['missing_maps'])))?></p><pre><?=e(json_encode($preview['settings'],JSON_PRETTY_PRINT))?></pre><?php if($preview['compatible']&&!$preview['saved']):?><button class="button" name="action" value="import">Import named preset</button><?php endif;endif?></form></div><p><a href="/server-console?server=<?=e(rawurlencode($id))?>">Return to server console</a></p></section><?php
}
